package com.bank.core;

import java.util.*;
import java.util.logging.*;

public class BoxingDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int n = 5_000_000;

        // 1) Autoboxing in a loop: Integer accumulator boxes every iteration.
        long startBoxed = System.nanoTime();
        Integer boxedTotal = 0; // wrapper accumulator — BAD
        for (int i = 0; i < n; i++) {
            boxedTotal += 1; // unbox → add → Integer.valueOf(...) → new object each time
        }
        long boxedMs = (System.nanoTime() - startBoxed) / 1_000_000;
        log.warning(() -> "Boxed Integer loop: total=" + boxedTotal
                           + " took " + boxedMs + " ms (heavy allocation)");

        // 2) Primitive accumulator: zero boxing, far faster.
        long startPrim = System.nanoTime();
        long primTotal = 0; // primitive accumulator — GOOD
        for (int i = 0; i < n; i++) {
            primTotal += 1;
        }
        long primMs = (System.nanoTime() - startPrim) / 1_000_000;
        log.info(() -> "Primitive long loop: total=" + primTotal
                        + " took " + primMs + " ms (no allocation)");

        // 3) Integer cache: == works only in -128..127
        Integer smallA = 100, smallB = 100;       // cached → same object
        Integer bigA = 1000, bigB = 1000;          // outside cache → new objects
        log.info(() -> "Integer 100 == 100  : " + (smallA == smallB) + " (cached, same ref)");
        log.warning(() -> "Integer 1000 == 1000: " + (bigA == bigB) + " (NOT cached, diff ref)");
        log.info(() -> "Integer 1000.equals(1000): " + bigA.equals(bigB) + " (value compare — CORRECT)");

        // 4) Unboxing a null wrapper throws NullPointerException
        Map<String, Integer> pending = new HashMap<>();
        pending.put("SAV2001", 3); // Rajesh has 3 pending
        Integer priyaPending = pending.get("CUR3001"); // not present → null
        try {
            int count = priyaPending; // unboxing null → NPE
            log.info(() -> "Priya pending = " + count);
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Unboxing null Integer threw NPE", e);
        }
        // Safe fix: default when absent
        int safeCount = pending.getOrDefault("CUR3001", 0);
        log.info(() -> "Safe Priya pending (getOrDefault) = " + safeCount);
    }
}
